@page "/"

@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍳 Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mt-1">
    @foreach (var category in Recipes.GetCategories())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h4 class="card-title">@CategoryEmoji(category) @category</h4>
                    <p class="card-text text-muted">
                        @Recipes.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="@($"category/{category}")" class="btn btn-outline-primary">
                        View Recipes
                    </a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-5">⭐ Top Rated</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mt-1">
    @foreach (var recipe in Recipes.GetFeatured())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">@recipe.Category</p>
                    <p>
                        @for (int i = 1; i <= 5; i++)
                        {
                            <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                        }
                        <span class="ms-1 text-muted">(@recipe.AverageRating)</span>
                    </p>
                    <a href="@($"recipe/{recipe.Id}")" class="btn btn-sm btn-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        "Mediterranean" => "🫒",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p>
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                            }
                            <span class="ms-1 text-muted">
                                (@recipe.AverageRating — @recipe.Ratings.Count ratings)
                            </span>
                        </p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"

@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        @if (recipe is not null)
        {
            <li class="breadcrumb-item"><a href="@($"category/{recipe.Category}")">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        }
    </ol>
</nav>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="card mb-4">
        <div class="card-header"><strong>Ingredients</strong></div>
        <ul class="list-group list-group-flush">
            @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
            {
                <li class="list-group-item">@ingredient</li>
            }
        </ul>
    </div>

    <div class="card mb-4">
        <div class="card-header"><strong>Steps</strong></div>
        <div class="card-body">
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>

    <h4>Rate this Recipe</h4>
    <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(RecipeId);
    }
}

@using RecipeShare.Services
@inject RecipeService Recipes

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-3 text-decoration-none"
                @onclick="() => Rate(star)"
                title="@star star(s)"
                style="color: @(star <= (selectedRating ?? 0) ? "gold" : "#ccc"); cursor: pointer;">
            @(star <= (selectedRating ?? 0) ? "★" : "☆")
        </button>
    }

    @if (submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }
</div>

@if (recipe is not null)
{
    <div class="text-muted mt-1">
        Average: @recipe.AverageRating / 5 (@recipe.Ratings.Count ratings)
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private int? selectedRating;
    private bool submitted;
    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        selectedRating = stars;
        Recipes.AddRating(RecipeId, stars);
        recipe = Recipes.GetById(RecipeId);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

@using System.ComponentModel.DataAnnotations
@using RecipeShare.Services
@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" />
        <ValidationMessage For="() => model.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-select">
            <option value="">— Select a category —</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Asian">Asian</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="Mediterranean">Mediterranean</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="4"
                       placeholder="Comma-separated list of ingredients" />
        <ValidationMessage For="() => model.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="6"
                       placeholder="One step per line" />
        <ValidationMessage For="() => model.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();

    private void HandleSubmit()
    {
        Recipes.AddRecipe(model.Title, model.Category, model.Ingredients, model.Steps);
        Nav.NavigateTo("/");
    }

    private sealed class RecipeFormModel
    {
        [Required(ErrorMessage = "Title is required.")]
        [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3-100 characters.")]
        public string Title { get; set; } = "";

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = "";

        [Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = "";
    }
}

