@page "/"

@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍳 Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mt-1">
    @foreach (var category in Recipes.GetCategories())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h4 class="card-title">@CategoryEmoji(category) @category</h4>
                    <p class="card-text text-muted">
                        @Recipes.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="@($"category/{category}")" class="btn btn-outline-primary">
                        View Recipes
                    </a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-5">⭐ Top Rated</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mt-1">
    @foreach (var recipe in Recipes.GetFeatured())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">@recipe.Category</p>
                    <p>
                        @for (int i = 1; i <= 5; i++)
                        {
                            <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                        }
                        <span class="ms-1 text-muted">(@recipe.AverageRating)</span>
                    </p>
                    <a href="@($"recipe/{recipe.Id}")" class="btn btn-sm btn-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        "Mediterranean" => "🫒",
        _ => "🍽️"
    };
}

namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count == 0 ? 0 : Math.Round(Ratings.Average(), 1);
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            Ratings = [5, 4, 5, 4, 5]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Egg yolks, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk egg yolks with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale and remove from heat.\n5. Stir in egg mixture quickly to create a creamy sauce.\n6. Serve immediately with extra Pecorino.",
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pot.\n4. Add tomato sauce and simmer 15 minutes.\n5. Stir in cream and add chicken pieces.\n6. Simmer 10 minutes and serve with rice.",
            Ratings = [5, 4, 4, 5]
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Garlic, Eggs",
            Steps = "1. Soak rice noodles in warm water 20 minutes.\n2. Press and cube tofu, then pan-fry until golden.\n3. Mix tamarind paste, fish sauce, and sugar for the sauce.\n4. Stir-fry garlic, then add eggs and scramble.\n5. Add noodles and sauce, toss until coated.\n6. Top with bean sprouts, peanuts, and lime wedges.",
            Ratings = [4, 4, 5]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Cumin, Chili powder, Garlic",
            Steps = "1. Brown ground beef with cumin, chili powder, and garlic.\n2. Warm taco shells in the oven.\n3. Shred lettuce and dice tomatoes.\n4. Fill shells with seasoned beef.\n5. Top with cheese, lettuce, tomato, and sour cream.\n6. Serve with salsa and lime.",
            Ratings = [4, 5, 4, 4]
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract",
            Steps = "1. Preheat oven to 425°F and butter ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs, sugar, and vanilla until thick.\n4. Fold chocolate mixture into eggs, then add flour.\n5. Pour into ramekins and bake 12-14 minutes.\n6. Invert onto plates and serve immediately.",
            Ratings = [5, 5, 5, 4, 5]
        },
        new()
        {
            Id = 7, Title = "Greek Salad", Category = "Mediterranean",
            Ingredients = "Cucumber, Tomatoes, Red onion, Kalamata olives, Feta cheese, Olive oil, Red wine vinegar, Oregano",
            Steps = "1. Chop cucumber, tomatoes, and red onion into chunks.\n2. Add Kalamata olives.\n3. Crumble feta cheese over the top.\n4. Whisk olive oil, vinegar, and oregano for dressing.\n5. Pour dressing over salad and toss gently.\n6. Serve chilled.",
            Ratings = [4, 3, 4]
        },
        new()
        {
            Id = 8, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt",
            Steps = "1. Halve and pit ripe avocados.\n2. Mash avocado to desired consistency.\n3. Finely dice onion, jalapeño, tomato, and cilantro.\n4. Mix all ingredients together.\n5. Add lime juice and salt to taste.\n6. Serve with tortilla chips.",
            Ratings = [5, 4, 5]
        }
    ];

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public IReadOnlyList<Recipe> GetFeatured() =>
        _recipes.OrderByDescending(r => r.AverageRating).Take(3).ToList();

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

