@page "/"

@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍳 Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mt-1">
    @foreach (var category in Recipes.GetCategories())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h4 class="card-title">@CategoryEmoji(category) @category</h4>
                    <p class="card-text text-muted">
                        @Recipes.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="@($"category/{category}")" class="btn btn-outline-primary">
                        View Recipes
                    </a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-5">⭐ Top Rated</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mt-1">
    @foreach (var recipe in Recipes.GetFeatured())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">@recipe.Category</p>
                    <p>
                        @for (int i = 1; i <= 5; i++)
                        {
                            <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                        }
                        <span class="ms-1 text-muted">(@recipe.AverageRating)</span>
                    </p>
                    <a href="@($"recipe/{recipe.Id}")" class="btn btn-sm btn-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        "Mediterranean" => "🫒",
        _ => "🍽️"
    };
}

